template:
{%- macro action(a, label, class, disabled=false) -%}
{%- if a.method in ("POST", "PUT", "PATCH", "DELETE") -%}
<button type="button" class="{{ class }}" hx-{{ a.method|lower }}="{{ in_mount(a.href) }}" hx-ext="scrud-json" hx-swap="none" data-scrud-json="fixed" data-scrud-body='{{ a.body|tojson }}' data-scrud-etag="{{ a.etag or '' }}"{% if disabled %} disabled{% endif %}>{{ label }}</button>
{%- endif -%}
{%- endmacro -%}
{%- set actions = value.actions or {} -%}
{%- set promote = actions.promote or [] -%}
{%- set changed = value.changed|length -%}
{%- set conflicts = value.conflicts|length -%}
<div class="studio-status" data-studio-status data-studio-endpoints='{{ value.endpoints|tojson }}'>
<ol class="studio-chain" aria-label="Chain">
{%- for branch in value.chain %}<li class="studio-chain-branch{% if branch.published %} studio-chain-published{% endif %}">{{ branch.name }}</li>{% endfor -%}
</ol>
<span class="studio-count" data-studio-changed="{{ changed }}">{{ changed }} changed</span>
<span class="studio-count{% if conflicts %} studio-count-conflicts{% endif %}" data-studio-conflict-count="{{ conflicts }}">{{ conflicts }} conflict{{ "" if conflicts == 1 else "s" }}</span>
<span class="studio-actions">
{%- if actions.pull %}{{ action(actions.pull, "Pull", "studio-pull") }}{% endif -%}
</span>
{%- if value.browse_url %}
<a class="studio-browse" href="{{ value.browse_url }}">Browse app on this branch</a>
{%- endif %}
{%- if promote %}
{%- set previews = in_mount(api_url("ui-push-previews", value.branch)) %}
<div class="studio-promotes">
{%- for entry in promote %}
{%- set panel = "studio-promote-" ~ loop.index %}
<div class="studio-promote" data-studio-promote="{{ entry.target }}" data-studio-promote-src="{{ previews }}">
<button type="button" class="studio-promote-open" data-studio-promote-open aria-expanded="false" aria-controls="{{ panel }}">Promote to {{ entry.target }}…</button>
<div class="studio-promote-panel" id="{{ panel }}" data-studio-promote-panel role="region" aria-label="Promote to {{ entry.target }}" hidden>
<div class="studio-promote-review" data-studio-promote-review></div>
<p class="studio-promote-reason" data-studio-promote-reason role="status" hidden></p>
<p class="studio-promote-note" data-studio-promote-note role="status" hidden></p>
<div class="studio-promote-actions">
<button type="button" class="studio-after-push" data-studio-after-push>Preview after push</button>
{%- if entry.apply %}{{ action(entry.apply, "Apply to " ~ entry.target, "studio-apply", true) }}{% endif -%}
{%- if entry.propose %}{{ action(entry.propose, "Propose to " ~ entry.target, "studio-propose") }}{% endif -%}
</div>
</div>
</div>
{%- endfor %}
</div>
{%- endif %}
{%- if value.pushes %}
<details class="studio-pushes">
<summary>Pushes ({{ value.pushes|length }})</summary>
<ul class="studio-push-list">
{%- for push in value.pushes %}
<li class="studio-push-entry" data-studio-push-state="{{ push.state }}"><a class="studio-push-link" href="{{ in_mount(push.href) }}?ui-scope=studio">{{ push.source if push.source is not none else "restore" }} → {{ push.target }}</a> <span class="studio-push-state">{{ push.state }}</span>{% if push.label %} <span class="studio-push-label">{{ push.label }}</span>{% endif %}</li>
{%- endfor %}
</ul>
</details>
{%- endif %}
</div>
